/**
 * 序列化后的错误对象
 *
 * 用于在跨窗口通信时传递错误信息，因为原生 Error 对象无法直接序列化
 */
export interface SerializedError {
    /**
     * 错误名称
     * @example 'TypeError', 'NetworkError'
     */
    name: string;
    /**
     * 错误消息
     */
    message: string;
    /**
     * 错误代码
     * 可以是数字或字符串类型的错误码
     */
    code?: number | string;
    /**
     * 错误堆栈信息
     * 用于调试和错误追踪
     */
    stack?: string;
    /**
     * 错误原因
     * 用于错误链追踪
     */
    cause?: unknown;
}
